<template>
  <div class="docnet-inbox" data-test="docnet-inbox-page">
    <!-- Header -->
    <div class="inbox-header row items-center q-mb-md">
      <h2 class="docnet-page-title">{{ $t('docnet_inbox') }}</h2>
      <q-badge v-if="inboxStore.pendingCount > 0" color="warning" class="q-ml-sm">
        {{ inboxStore.pendingCount }}
      </q-badge>
      <q-space />
      <q-btn-toggle
        v-model="statusFilter"
        no-caps
        rounded
        unelevated
        toggle-color="primary"
        color="white"
        text-color="primary"
        :options="statusFilterOptions"
        class="inbox-filter-toggle q-mr-sm"
      />
    </div>

    <!-- Loading -->
    <div v-if="inboxStore.loading" class="text-center q-pa-xl">
      <q-spinner-dots color="primary" size="40px" />
    </div>

    <!-- Empty -->
    <div v-else-if="displayItems.length === 0" class="text-center q-pa-xl">
      <q-icon name="check_circle" size="64px" color="positive" />
      <p class="q-mt-md text-grey-6">
        {{ statusFilter === 'pending' ? $t('docnet_no_pending_items') : $t('docnet_no_inbox_items') }}
      </p>
    </div>

    <!-- Item list -->
    <div v-else class="inbox-list">
      <q-card
        v-for="item in displayItems"
        :key="item.id"
        flat
        bordered
        class="inbox-card"
      >
        <InboxDropdownItem
          :item="item"
          @select="onSelect"
          @act="onAct"
          @dismiss="onDismiss"
        />
      </q-card>
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { useDocNetInboxStore } from 'src/store/DocNet/docnet-inbox.store';
import { useDocNetMissionStore } from 'src/store/DocNet/docnet-missions.store';
import { useDocNetWebSocketStore } from 'src/store/DocNet/docnet-websocket.store';
import { getOrgId } from 'src/utils/organization/org_id_helper';
import type { DocNetInboxItem } from 'src/@types/docnet';
import InboxDropdownItem from '../shared/InboxDropdownItem.vue';

export default defineComponent({
  name: 'DocNetInbox',

  components: {
    InboxDropdownItem,
  },

  setup() {
    const inboxStore = useDocNetInboxStore();
    const missionStore = useDocNetMissionStore();
    return { inboxStore, missionStore };
  },

  data() {
    return {
      statusFilter: 'pending' as string,
    };
  },

  computed: {
    statusFilterOptions() {
      return [
        { label: this.$t('docnet_pending'), value: 'pending' },
        { label: this.$t('docnet_resolved'), value: 'resolved' },
        { label: this.$t('docnet_all'), value: 'all' },
      ];
    },

    displayItems(): DocNetInboxItem[] {
      let items = this.inboxStore.activeItems;

      if (this.statusFilter !== 'all') {
        if (this.statusFilter === 'resolved') {
          items = items.filter((i) => i.status === 'resolved' || i.status === 'dismissed');
        } else {
          items = items.filter((i) => i.status === this.statusFilter);
        }
      }

      return items.sort(
        (a, b) => new Date(b.created_on).getTime() - new Date(a.created_on).getTime(),
      );
    },
  },

  async mounted() {
    await Promise.all([
      this.inboxStore.fetchItems(),
      this.missionStore.fetchMissions(),
    ]);
    const orgId = getOrgId();
    if (orgId) {
      useDocNetWebSocketStore().subscribe(`inbox:${orgId}`);
    }
  },

  beforeUnmount() {
    const orgId = getOrgId();
    if (orgId) {
      useDocNetWebSocketStore().unsubscribe(`inbox:${orgId}`);
    }
  },

  methods: {
    onSelect(id: string) {
      const item = this.inboxStore.activeItems.find((i) => i.id === id);
      if (item?.mission_id) {
        this.$router.push('/doc-net/missions/' + item.mission_id);
      }
    },

    async onAct(event: { id: string; action: 'approve' | 'reject' | 'reassign' | 'comment'; payload?: Record<string, unknown> }) {
      try {
        // The backend act_on_item handles everything:
        // - Tool-level approvals: executes the tool + resets issue/mission
        // - Standard approvals: schedules orchestrator resume
        await this.inboxStore.actOnItem(event.id, event.action, event.payload);
      } catch (error) {
        console.error('[DocNet] Inbox act failed:', error);
      }
    },

    async onDismiss(id: string) {
      try {
        await this.inboxStore.dismissItem(id);
      } catch (error) {
        console.error('[DocNet] Inbox dismiss failed:', error);
      }
    },
  },
});
</script>

